class Solution {
public:
 int countTrapezoids(vector<vector<int>>& points){const long long MOD=1000000007;unordered_map<int,long long>cnt;for(auto&p:points)++cnt[p[1]];
 long long total=0,ans=0;for(auto &p:cnt){long long ways=p.second*(p.second-1)/2%MOD;ans=(ans+total*ways)%MOD;total=(total+ways)%MOD;}return ans;}
};
